.grid-overlay{position:absolute;inset:0;pointer-events:none;z-index:0;background-repeat:no-repeat;background-position:30px 0;background-size:calc(100% - 60px) 100%;background-image:repeating-linear-gradient(90deg,#9797c9 0 1px,transparent 1px 97px,#9797c9 97px 98px,transparent 98px 112px)}
